def is_mc_correct(schedule, dag_set):
    # Check LO-Mode
    for dag in dag_set:
        for vertex in dag.hi_vertices:
            if not completes_by_lo_deadline(vertex):
                return False
    # Check HI-Mode on TFE simulation
    simulate_tfe(schedule)
    for dag in dag_set:
        for vertex in dag.hi_vertices:
            if not completes_by_hi_deadline(vertex):
                return False
    return True
